description = "Build the fixed benchmark subject"
run = "mbx build --release --locked -p mbx"

[tasks."build:pgo"]
description = "Build a profile-guided mbx release binary"
run = "benchmarks/pgo.bash"

[tasks.perf]
description = "Measure instruction-counted performance benchmarks"
depends = ["perf:prepare"]
run = "tak run"

# Real-world comparison against raw cargo and kache, on a pinned third-party
# project. Long-running by nature: every cell is a full build of somebody
# else's workspace. See benchmarks/README.md.
[tasks.bench]
description = "Compare cargo, mbx, and kache on a pinned real-world project"
depends = ["perf:prepare"]
run = """
python3 benchmarks/real_world.py \
  --mbx target/release/mbx \
  --scenarios warm,commit,edit \
  --output target/benchmarks
"""

# What CI runs. Adds the contention batch, repeats every scenario so the site
