/// Where the session tells the shim to keep stable trees.
pub(crate) const ROOT_ENV: &str = "MBX_OUT_DIR_ROOT";

/// The cache-relative home of stable trees.
pub(crate) const ROOT: &str = "out-dirs/v1";

